'use strict';
const BOOTSTRAP_UI6={supplyView,roastersView,bind,help};
function coffeeSupplierLocations6(){return [...state.stores.filter(s=>!s.franchise).map(s=>s.id),...state.opening6.projects.filter(p=>p.kind==='cafe'&&!p.franchise&&p.status==='active'&&!p.entity).map(p=>p.location)];}
function coffeeSuppliersUI6(){const targets=coffeeSupplierLocations6();return `<section class="card" style="margin-bottom:24px"><h2>Dodavatelé hotové kávy</h2><p>Kavárnu můžeš zásobovat bez vlastní pražírny nebo distribučního skladu. Platíš konkrétní kg a dopravu; zásilka přijde za jeden týden do připraveného prostoru.</p><p class="sub">Zásoby se v tomto modelu sdílí mezi kavárnami stejného města a stejné směsi. Smlouva doplňuje jejich společnou zásobu; každý kg se spotřebuje pouze jednou. Vlastní rozvoz mezi městy má samostatné trasy.</p>${targets.length?`<div class="fields">${field('Kavárna nebo její příprava',`<select id="coffeeSupplierLocation6">${targets.map(id=>option(id,loc(id).city+' · '+loc(id).name,null)).join('')}</select>`)}${field('Dodavatel',`<select id="coffeeSupplierProvider6">${Object.entries(COFFEE_SUPPLIERS6).map(([k,p])=>option(k,p.name+' · '+money(p.price)+'/kg · kvalita '+p.quality,'local')).join('')}</select>`)}${field('Receptura',`<select id="coffeeSupplierBlend6">${blendOptions(state.blends[0].id)}</select>`)}${field('Cílová zásoba / jednorázové kg',input('coffeeSupplierTarget6',25,5,100,1))}${field('Týdenní limit automatických objednávek',input('coffeeSupplierBudget6',20000,0,100000,500))}${field('Hotovostní rezerva · týdny',input('coffeeSupplierReserve6',1,1,8))}</div><div class="actions"><button class="primary" id="coffeeSupplierSign6">Prověřit smlouvu</button><button class="soft" id="coffeeSupplierOrder6">Prověřit jednorázový nákup</button></div><p class="sub">Sjednání stojí 3 000 / 5 000 Kč. Každá dodávka má navíc 400 / 500 Kč dopravu. Smlouva začne objednávat ve fázi náboru; jednorázový nákup také vyžaduje připravený prostor. Bez smlouvy můžeš nakupovat ručně. Cíle kaváren se stejnou směsí se ve městě sčítají. Objednávka počítá i spotřebu do doručení. Rozpočet a rezerva mohou automatickou objednávku zastavit.</p>`:'<p class="sub">Nejdřív vyber adresu a zahaj přípravu kavárny. Založení firmy nevytváří smlouvu ani kávu zdarma.</p><button class="primary" data-goto="city">Vybrat první prostor</button>'}<h3>Skutečné smlouvy a jejich rozhodnutí</h3>${state.bootstrap6.suppliers.filter(a=>a.status==='active').map(a=>`<article><strong>${esc(loc(a.location).name)} · ${COFFEE_SUPPLIERS6[a.provider].name}</strong><p>${a.enabled?'Automatika aktivní':'Pozastaveno'} · cíl ${a.target} kg · limit ${money(a.budget)} · rezerva ${a.reserve} týdny</p><p class="sub">${esc(a.last?.reason||'Čeká na další skutečný týden.')} ${a.last?.spent?'Zaplaceno '+money(a.last.spent)+'.':''}</p><div class="actions"><button class="soft mini" data-coffee-supplier-toggle6="${a.id}">${a.enabled?'Pozastavit':'Obnovit'}</button><button class="soft mini" data-coffee-supplier-edit6="${a.id}">Upravit cíl a limity</button><button class="quiet mini" data-coffee-supplier-cancel6="${a.id}">Ukončit smlouvu</button></div></article>`).join('')||empty('Žádný sjednaný dodavatel.')}<details><summary>Zaplacené dodávky a příjem kávy</summary><div class="table-scroll"><table class="data"><thead><tr><th>Kavárna / dodavatel</th><th>Objednávka</th><th>Skutečný stav</th></tr></thead><tbody>${state.bootstrap6.orders.slice(-30).reverse().map(o=>`<tr><td>${esc(loc(o.location).name)}<small>${COFFEE_SUPPLIERS6[o.provider].name}</small></td><td>${o.kg} kg · ${money(o.cost)}<small>Zaplaceno T${o.ordered}</small></td><td>${o.received===null?'Na cestě · od T'+o.due:'Vyřízeno T'+o.received}</td></tr>`).join('')||'<tr><td colspan="3">Zatím žádná zaplacená káva.</td></tr>'}</tbody></table></div></details></section>`;}
supplyView=function(){return coffeeSuppliersUI6()+BOOTSTRAP_UI6.supplyView();};
roastersView=function(){return `<p class="intro">Vlastní pražírna je pozdější výrobní investice. První kavárnu zásobuje sjednaný dodavatel hotové kávy; vlastní pražírna na začátku neexistuje.</p><button class="soft" data-goto="supply">Dodavatelé hotové kávy</button>`+BOOTSTRAP_UI6.roastersView();};
function supplierRead6(){return {location:el('coffeeSupplierLocation6').value,provider:el('coffeeSupplierProvider6').value,blend:el('coffeeSupplierBlend6').value,target:Number(el('coffeeSupplierTarget6').value),budget:Number(el('coffeeSupplierBudget6').value),reserve:Number(el('coffeeSupplierReserve6').value),enabled:true};}
function supplierEditDialog6(id){const a=state.bootstrap6.suppliers.find(a=>a.id===id&&a.status==='active');if(!a)return;show(`<h2>Mandát dodavatele · ${esc(loc(a.location).name)}</h2><p>Cíl je zásoba po očekávané spotřebě do doručení. Kavárny se stejnou směsí sdílejí městský sklad; jejich cíle se sčítají.</p><p class="sub">${esc(cafeCoffeeStatus6(a.location,a.blend).text)}</p><label class="checkbox-line"><input type="checkbox" id="supplierEditEnabled6" ${a.enabled?'checked':''}>Automaticky objednávat kávu</label><div class="fields">${field('Cílová zásoba kg',input('supplierEditTarget6',a.target,5,100))}${field('Týdenní rozpočet',input('supplierEditBudget6',a.budget,0,100000,500))}${field('Rezerva · týdny',input('supplierEditReserve6',a.reserve,1,8))}</div><button class="primary" id="supplierEditSave6">Uložit mandát</button>`);el('supplierEditSave6').onclick=()=>{try{setCoffeeAgreement6(id,{enabled:el('supplierEditEnabled6').checked,target:Number(el('supplierEditTarget6').value),budget:Number(el('supplierEditBudget6').value),reserve:Number(el('supplierEditReserve6').value)});persist();render();el('modal').close();}catch(e){toast(e.message);}};}
purchaseRoasterDialog=function(){show(`<h2>Příprava vlastní pražírny</h2><div class="fields">${field('Název','<input id="roasterName" maxlength="40" value="Nová pražírna">')}${field('Typ',`<select id="roasterType">${ROASTER_OPTIONS.map(o=>option(o.id,o.name+' · '+money(o.cost),'artisan')).join('')}</select>`)}${field('Město',`<select id="roasterCity6">${CITIES.map(c=>option(c.name,c.name,'Praha')).join('')}</select>`)}</div><div id="roasterPreview"></div><button class="primary" id="roasterConfirm">Zahájit přípravu</button>`);let q;const read=()=>({type:el('roasterType').value,name:el('roasterName').value,city:el('roasterCity6').value}),preview=()=>{try{q=openingQuote6('roaster',read());el('roasterPreview').innerHTML=rows([['Platba nyní',money(q.cost)],['Plán přípravy',q.totalWeeks+' týdnů'],['Držení místa / týden',money(q.holdingRent)],['Skuteční pracovníci při náboru',q.need],['Pozdější placený nábor',money(q.need*8000)]])+'<p class="sub">Mzdy a odvody začnou při náboru. Během zkoušky je k dispozici polovina kapacity; žádná zelená káva není v kupní ceně.</p>';el('roasterConfirm').disabled=state.cash<q.cost||state.over;}catch(e){q=null;el('roasterPreview').textContent=e.message;el('roasterConfirm').disabled=true;}};el('roasterType').onchange=el('roasterCity6').onchange=el('roasterName').oninput=preview;preview();el('roasterConfirm').onclick=()=>{try{if(!q)throw Error('Vyber platnou přípravu.');const p=startOpening6('roaster',read(),q);persist();render();openingProjectDialog6(p.id);}catch(e){toast(e.message);}};};
function supplierSelection6(){const id=el('coffeeSupplierLocation6')?.value;if(!id)return;const target=coffeeSupplierTarget6(id),a=state.bootstrap6.suppliers.find(a=>a.location===id&&a.status==='active');el('coffeeSupplierSign6').textContent=a?'Upravit sjednaného dodavatele':'Prověřit smlouvu';el('coffeeSupplierBlend6').value=a?.blend||target?.blend||target?.blueprint?.blend||state.blends[0].id;if(a){el('coffeeSupplierProvider6').value=a.provider;el('coffeeSupplierTarget6').value=a.target;el('coffeeSupplierBudget6').value=a.budget;el('coffeeSupplierReserve6').value=a.reserve;}}
bind=function(){BOOTSTRAP_UI6.bind();if(el('coffeeSupplierLocation6')){el('coffeeSupplierLocation6').onchange=supplierSelection6;supplierSelection6();}if(el('coffeeSupplierSign6'))el('coffeeSupplierSign6').onclick=()=>{try{const d=supplierRead6(),existing=state.bootstrap6.suppliers.find(a=>a.location===d.location&&a.status==='active');if(existing)return supplierEditDialog6(existing.id);const data={target:d.target,budget:d.budget,reserve:d.reserve,enabled:d.enabled},q=coffeeAgreementQuote6(d.provider,d.location,d.blend,data);confirmAction('Sjednat dodávky hotové kávy?',COFFEE_SUPPLIERS6[d.provider].name+' · '+money(q.fee)+' nyní. Cíl '+q.target+' kg, týdenní limit '+money(q.budget)+', rezerva '+q.reserve+' týdny. Každý nákup kávy a doprava se platí zvlášť.',()=>signCoffeeAgreement6(d.provider,d.location,d.blend,data,q),'Sjednat dodavatele');}catch(e){toast(e.message);}};
 if(el('coffeeSupplierOrder6'))el('coffeeSupplierOrder6').onclick=()=>{try{const d=supplierRead6(),q=supplierCoffeeQuote6(d.provider,d.location,d.blend,d.target);confirmAction('Zaplatit konkrétní dodávku kávy?',q.kg+' kg · '+money(q.cost)+' včetně dopravy, doručení od T'+q.due+'. Náhled zatím nic neobjednal.',()=>orderSupplierCoffee6(d.provider,d.location,d.blend,d.target,q),'Zaplatit a objednat');}catch(e){toast(e.message);}};
 on('[data-coffee-supplier-toggle6]',b=>act(()=>{const a=state.bootstrap6.suppliers.find(a=>a.id===b.dataset.coffeeSupplierToggle6);setCoffeeAgreement6(a.id,{enabled:!a.enabled,target:a.target,budget:a.budget,reserve:a.reserve});},'Mandát dodavatele změněn.'));
 on('[data-coffee-supplier-edit6]',b=>supplierEditDialog6(b.dataset.coffeeSupplierEdit6));on('[data-coffee-supplier-cancel6]',b=>confirmAction('Ukončit dodavatele?', 'Zaplacené zásilky se stále doručí. Sjednávací poplatek se nevrací.',()=>cancelCoffeeAgreement6(b.dataset.coffeeSupplierCancel6),'Ukončit smlouvu'));
};
help=function(){BOOTSTRAP_UI6.help();const p=document.createElement('p');p.textContent='Zakladatel začíná pouze s 500 000 Kč. Nemá kavárnu, vybavení, zaměstnance, sklad, kancelář, pražírnu ani kávu. Receptura a název značky jsou pouze výchozí návrhy. Prostor a vybavení zaplatíš při zahájení přípravy; konkrétní pracovníci mají placený nábor a mzdy. Hotovou kávu kupuješ od dodavatele. Zaplacená dodávka je zásoba na cestě, nikoli další provozní výdaj; do nákladů jde až spotřebovaná káva nebo odpis.';el('modalContent').append(p);};el('help').onclick=help;render();

const SUPPLIER_DIGEST_DESTINATION6=digestDestination6;
digestDestination6=function(x){if(x.key.startsWith('coffee-supplier-')&&state.bootstrap6.suppliers.some(a=>a.id===x.target&&a.status==='active')){closeDigest6();supplierEditDialog6(x.target);return;}SUPPLIER_DIGEST_DESTINATION6(x);};
